"""Lowest Common Ancestor of a BST — walk while both targets sit on one side.

The first node that splits p and q (or equals one of them) is the answer.

Time: O(h)   Space: O(1)
"""
if "TreeNode" not in globals():
    class TreeNode:
        def __init__(self, val=0, left=None, right=None):
            self.val = val
            self.left = left
            self.right = right


class Solution:
    def lowestCommonAncestor(self, root, p, q):
        node = root
        while node:
            if p.val < node.val and q.val < node.val:
                node = node.left
            elif p.val > node.val and q.val > node.val:
                node = node.right
            else:
                return node
        return None
